import { dgnUnpackTicket } from './dgn-traits.js';

/** Recover only point allocations that agree with the recorded result. Older
 * replays used symbol-gated color points. Never guess an ambiguous Hero. */
export function projectPopRow(row, defaultHero = null) {
  const player = dgnUnpackTicket(row.playerTraits);
  const house = row.houseTraits == null ? null : dgnUnpackTicket(row.houseTraits);
  const score = Math.max(0, Number(row.score) || 0);
  const rawHero = Object.hasOwn(row, 'heroIdx') ? row.heroIdx : defaultHero;
  const knownHero = rawHero != null && Number.isInteger(Number(rawHero))
    && Number(rawHero) >= 0 && Number(rawHero) < 4 ? Number(rawHero) : null;
  const heroes = knownHero == null
    ? (row.scoring === 'legacy' ? [null, 0, 1, 2, 3] : [0, 1, 2, 3])
    : [knownHero];
  let candidates = [];
  let legacy = false;
  if (house) for (const gated of row.scoring === 'legacy' ? [true] : [false, true]) {
    candidates = heroes.map(hero => ({
      hero,
      points: player.map((p, q) => {
        const symbol = p.sym === house[q].sym;
        return (symbol ? (q === hero ? 2 : 1) : 0)
          + (p.col === house[q].col && (!gated || symbol) ? 1 : 0);
      }),
    })).filter(c => c.points.reduce((a, b) => a + b, 0) === score);
    if (candidates.length) { legacy = gated; break; }
  }
  const unique = new Set(candidates.map(c => c.points.join(',')));
  const points = unique.size === 1 ? candidates[0].points : null;
  const hero = candidates.length === 1 ? candidates[0].hero
    : candidates.length ? knownHero : null;
  return {
    score, hero, legacy, exact: Boolean(points),
    quadrants: player.map((p, q) => ({
      player: p, house: house?.[q] ?? null,
      points: points?.[q] ?? null,
      symbolMatch: Boolean(house && p.sym === house[q].sym),
      colorMatch: Boolean(house && p.col === house[q].col),
      gold: Boolean(house && p.col === 7 && house[q].col === 7),
      hero: hero === q,
    })),
  };
}

/** Reveal state lives independently of DOM, timers, and animation completion. */
export function createPopState(rows, hero = null) {
  const boards = rows.map(row => projectPopRow(row, hero));
  const masks = boards.map(() => 0);
  const snapshot = () => ({
    masks: masks.slice(),
    complete: masks.every(mask => mask === 15),
    completed: masks.filter(mask => mask === 15).length,
    score: boards.reduce((total, board, i) => total + (board.exact
      ? board.quadrants.reduce((sum, q, j) => sum + ((masks[i] & (1 << j)) ? q.points : 0), 0)
      : masks[i] === 15 ? board.score : 0), 0),
  });
  return {
    boards, snapshot,
    reveal(index, mask = 15) {
      if (!Number.isInteger(index) || index < 0 || index >= boards.length) return [];
      const added = (Number(mask) & 15) & ~masks[index];
      masks[index] |= added;
      return boards[index].quadrants.flatMap((quadrant, q) => (
        added & (1 << q) ? [{ ...quadrant, board: index, quadrant: q }] : []
      ));
    },
  };
}
